set -euo pipefail
db_user=$(docker exec postgres printenv POSTGRES_USER)
docker exec -i postgres psql -X -qAt -v ON_ERROR_STOP=1 -U "$db_user" -d coaching_db <<'SQL'
SELECT json_build_object('exams',(SELECT json_agg(x) FROM (SELECT "Code","Name","ExamDate","IsActive" FROM coaching.study_catalog_exams ORDER BY "DisplayOrder","Code")x));
SELECT json_build_object('groups',(SELECT count(*) FROM coaching.study_catalog_lesson_groups),'lessons',(SELECT count(*) FROM coaching.study_catalog_lessons),'activeLessons',(SELECT count(*) FROM coaching.study_catalog_lessons WHERE "IsActive"),'units',(SELECT count(*) FROM coaching.study_catalog_units),'activeUnits',(SELECT count(*) FROM coaching.study_catalog_units WHERE "IsActive"),'topics',(SELECT count(*) FROM coaching.study_catalog_topics),'activeTopics',(SELECT count(*) FROM coaching.study_catalog_topics WHERE "IsActive"),'rootTopics',(SELECT count(*) FROM coaching.study_catalog_topics WHERE "ParentId" IS NULL),'childTopics',(SELECT count(*) FROM coaching.study_catalog_topics WHERE "ParentId" IS NOT NULL),'topicsWithMinutes',(SELECT count(*) FROM coaching.study_catalog_topics WHERE "EstimatedMinutes" IS NOT NULL));
SELECT json_build_object('curricula',(SELECT count(*) FROM coaching.curriculum_versions),'officialEditions',(SELECT count(*) FROM coaching.official_curriculum_editions),'officialTopics',(SELECT count(*) FROM coaching.official_curriculum_topics),'outcomes',(SELECT count(*) FROM coaching.study_catalog_outcomes),'activeOutcomes',(SELECT count(*) FROM coaching.study_catalog_outcomes WHERE NOT "IsArchived"),'mappings',(SELECT count(*) FROM coaching.study_catalog_topic_outcomes),'approvedMappings',(SELECT count(*) FROM coaching.study_catalog_topic_outcomes WHERE "IsApproved"),'mappedTopics',(SELECT count(DISTINCT "TopicId") FROM coaching.study_catalog_topic_outcomes WHERE "IsApproved"),'durationRows',(SELECT count(*) FROM coaching.outcome_duration_estimates),'publishedDurationRows',(SELECT count(*) FROM coaching.outcome_duration_estimates WHERE "IsPublished"),'outcomesWithPublishedDurations',(SELECT count(DISTINCT "OutcomeId") FROM coaching.outcome_duration_estimates WHERE "IsPublished"));
SELECT json_agg(x) FROM (SELECT coalesce(l."ExamCode",'Sınıf/genel') AS exam,count(DISTINCT l."Id") AS lessons,count(DISTINCT u."Id") AS units,count(DISTINCT t."Id") AS topics FROM coaching.study_catalog_lessons l LEFT JOIN coaching.study_catalog_units u ON u."LessonId"=l."Id" LEFT JOIN coaching.study_catalog_topics t ON t."LessonId"=l."Id" GROUP BY l."ExamCode" ORDER BY l."ExamCode" NULLS FIRST)x;
SELECT json_agg(x) FROM (SELECT e."Code",e."ExamCode",e."GradeNumber",e."SubjectName",e."AcademicYearStart",e."AcademicYearEnd",count(DISTINCT o."Id") AS outcomes,count(DISTINCT d."OutcomeId") FILTER(WHERE d."IsPublished") AS with_published_duration FROM coaching.official_curriculum_editions e LEFT JOIN coaching.study_catalog_outcomes o ON o."EditionId"=e."Id" LEFT JOIN coaching.outcome_duration_estimates d ON d."OutcomeId"=o."Id" GROUP BY e."Id")x;
SELECT json_agg(x) FROM (SELECT "Method","Confidence","IsPublished",min("Number") AS min_version,max("Number") AS max_version,count(*) AS count,sum("LearningMinutes") AS learning,sum("PracticeMinutes") AS practice,sum("CheckMinutes") AS check_minutes FROM coaching.outcome_duration_estimates GROUP BY "Method","Confidence","IsPublished")x;
SQL
